Ptc [] ptcs;

let gMag = 1, gVelMax = 10, gThres, gThresT, gBgAlpha = 255, gBgAlphaT = 255;

function setup() {
  createCanvas(960, 720);
  frameRate(30);
  smooth();
  textSize(15);
  background(255);
  initPtcs(60);
  initSliders();
}
function draw() {

  gThres = lerp(gThres, gThresT, .02);
  gBgAlpha = lerp(gBgAlpha, gBgAlphaT, .02);
  gMag = sliderForce.value;

  updatePtcs();
  updateSliders();

  noStroke();
  fill(255, gBgAlpha);
  rect(0, 0, width, height);

  drawPtcs();
  drawCnts();
  drawSliders();
}
function initPtcs(amt) {
  ptcs = new Array(amt);
  for (i=0; i<ptcs.length; i++) {
    ptcs[i] = new Ptc();
  }
}

function updatePtcs() {
  if (onPressed) {
    for (i=0; i<ptcs.length; i++) {
      ptcs[i].update((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    }
  } else {
    for (i=0; i<ptcs.length; i++) {
      ptcs[i].update();
    }
  }
}

function drawPtcs() {
  for (i=0; i<ptcs.length; i++) {
    ptcs[i].drawPtc();
  }
}

function drawCnts() {
  for (i=0; i<ptcs.length; i++) {
    for (j=i+1; j<ptcs.length; j++) {
      let d = dist(ptcs[i].pos.x, ptcs[i].pos.y, ptcs[j].pos.x, ptcs[j].pos.y);
      if (d<gThres) {
        let scalar = map(d, 0, gThres, 1, 0);
        ptcs[i].drawCnt(ptcs[j], scalar);
      }
    }
  }
}

class Ptc {

  pos, pPos, vel, acc;
  decay, weight, magScalar;

  constructor() {
    pos = new PVector(random(width), random(height));
    pPos = new PVector(pos.x, pos.y);
    vel = new PVector(0, 0);
    acc = new PVector(0, 0);

    weight = random(1, 10);
    decay = map(weight, 1, 10, .95, .85);
    magScalar = map(weight, 1, 10, .5, .05);
  }

  function update(tgtX, tgtY) {

    pPos.set(pos.x, pos.y);

    acc.set(tgtX-pos.x, tgtY-pos.y);

    //normalize() instead in let mode
    let accMag = sqrt(sq(acc.x)+sq(acc.y));
    acc.mult(1.0/accMag);
    //------------------------------
    acc.mult(gMag * magScalar);
    vel.add(acc);
    //limit() instead in let mode
    let velMag = sqrt(sq(vel.x)+sq(vel.y));
    if(velMag>gVelMax) vel.mult(gVelMax/velMag);
    //------------------------------
    pos.add(vel);
    acc.set(0, 0, 0);
    boundaryCheck();
  }

  function update() {

    pPos.set(pos.x, pos.y);

    vel.add(acc);
    vel.mult(decay);
    pos.add(vel);
    acc.set(0, 0);

    boundaryCheck();
  }

  function drawPtc() {
    strokeWeight(weight);
    stroke(0, 255);
    if(onPressed)line(pos.x, pos.y, pPos.x, pPos.y);
    else point(pos.x, pos.y);
  }

  function drawCnt(coPtc, scalar) {
    strokeWeight((weight+coPtc.weight)*.5*scalar);
    stroke(0, 255*scalar);
    line(pos.x, pos.y, coPtc.pos.x, coPtc.pos.y);
  }

  function boundaryCheck() {
    if (pos.x > width) {
      pos.x = width;
      vel.x *= -1;
    } else if (pos.x < 0) {
      pos.x = 0;
      vel.x *= -1;
    }
    if (pos.y > height) {
      vel.y *= -1;
    } else if (pos.y < 0) {
      vel.y *= -1;
    }
  }
}
ArrayList <Slider> slidersList;

let sliderGhost, sliderThres, sliderForce;

function initSliders(){

  slidersList = new ArrayList<Slider>();

  sliderGhost = new Slider(100, 30, 120, 20);
  sliderGhost.setTag("Fantasma");
  sliderGhost.setValue(32, 6, 255);
  sliderThres = new Slider(100, 55, 120, 20);
  sliderThres.setTag("Limite");
  sliderThres.setValue(100, 0, 240);
  sliderForce = new Slider(100, 80, 120, 20);
  sliderForce.setTag("Força");
  sliderForce.setValue(1, -1, 1);

  slidersList.add(sliderGhost);
  slidersList.add(sliderThres);
  slidersList.add(sliderForce);
}


function updateSliders(){
  for(i=0; i<slidersList.size(); i++){
    let slider = slidersList.get(i);
    if(slider.active){
      slider.update();
      break;
    }
  }
}

function drawSliders(){
  for(i=0; i<slidersList.size(); i++){
    var slider = slidersList.get(i);
    slider.display();
  }
}

class Slider{

  pos, nameTagPos, valueTagPos;
  w, h, innerW, value, valueMin, valueMax;
  active;
  nameTag, valueTag;

  constructor(x, y, w, h){
    pos = new PVector(x, y);
    nameTagPos = new PVector(x-10, y);
    valueTagPos = new PVector(x+w*.5, y);
    this.w = w;
    this.h = h;
  }

  function setTag(nameTag){
    this.nameTag = nameTag;
  }

  function setValue(value, valueMin, valueMax){
    this.value = value;
    this.valueMin = valueMin;
    this.valueMax = valueMax;

    valueTag = str(round(value*100)/100);

    innerW = map(value, valueMin, valueMax, 0, w);
  }

  function update(){
    innerW = constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-pos.x, 0, w);
    value = map(innerW, 0, w, valueMin, valueMax);
    valueTag = str(round(value*100)/100);
  }

  function display(){
    noStroke();
    fill(0);
    rect(pos.x, pos.y, w, h);
    fill(255, 0, 0);
    rect(pos.x, pos.y, innerW, h);

    fill(255);
    rect(pos.x-10-textWidth(nameTag), pos.y, 10+textWidth(nameTag), h);

    fill(0);
    textAlign(RIGHT, TOP);
    text(nameTag, nameTagPos.x, nameTagPos.y);

    fill(255);
    textAlign(CENTER, TOP);
    text(valueTag, valueTagPos.x, valueTagPos.y);
  }
}
let onPressed;

function mousePressed(){

  for(i=0; i<slidersList.size(); i++){
    var slider = slidersList.get(i);
    if((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))>slider.pos.x && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))<slider.pos.x+slider.w && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))>slider.pos.y && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))<slider.pos.y+slider.h){
      slider.active = true;
      return;
    }
  }

  onPressed = true;
  gThresT = sliderThres.value;
  gBgAlphaT = sliderGhost.value;
}

function mouseReleased(){

  for(i=0; i<slidersList.size(); i++){
    var slider = slidersList.get(i);
    slider.active = false;
  }

  onPressed = false;
  gThresT = 0;
  gBgAlphaT = 255;
}

